// main.ts — entrypoint for the make.fun "news-image-20261123" entry
// ("23 November 2026 — The Day in One Image", 1024x1024).
//
// The artwork itself is generated by render.py from stories.json (both in
// this repository) and the finished PNG ships here as entry.png. This
// program's one job is delivery: copy that image, byte for byte, to the
// place the grader reads — $MAKEFUN_OUTPUT_DIR/entry.png when the harness
// sets the variable, /output/entry.png otherwise. Byte-for-byte copying is
// what makes the run deterministic: same repository in, same image out.
//
// Runtime: Node 22, standard library only. No network, no dependencies.

import { copyFileSync, existsSync, mkdirSync, statSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const image = join(here, "entry.png");

if (!existsSync(image)) {
  console.error(`entry image missing from repository: ${image}`);
  process.exit(1);
}

const outDir = process.env.MAKEFUN_OUTPUT_DIR?.trim()
  ? resolve(process.env.MAKEFUN_OUTPUT_DIR)
  : "/output";
const target = join(outDir, "entry.png");

mkdirSync(outDir, { recursive: true });
copyFileSync(image, target);

console.log(`delivered ${target} (${statSync(target).size} bytes)`);
